#!/bin/sh
# Generated by release-plz. Downloads are pinned to this release and verified with SHA-256.
# Set RELEASE_PLZ_INSTALL_DIR to override ~/.local/bin. No shell profiles are changed.
release_plz_install() (
    set -eu
@@CONFIG@@
    os=$(uname -s)
    arch=$(uname -m)
    case "$arch" in
        x86_64|amd64) arch=x86_64 ;;
        aarch64|arm64) arch=aarch64 ;;
        *) printf 'Unsupported architecture: %s\n' "$arch" >&2; exit 1 ;;
    esac
    case "$os" in
        Linux)
            # A GNU binary cannot run on musl. GNU systems can fall back to static musl.
            case "$(ldd --version 2>&1 || :)" in
                *musl*) select_archive "$arch-unknown-linux-musl" ;;
                *) select_archive "$arch-unknown-linux-gnu" || select_archive "$arch-unknown-linux-musl" ;;
            esac || { printf 'No compatible Linux archive for %s in this release.\n' "$arch" >&2; exit 1; }
            ;;
        Darwin)
            # uname reports x86_64 when the shell runs under Rosetta.
            if [ "$arch" = x86_64 ] && [ "$(sysctl -n hw.optional.arm64 2>/dev/null || :)" = 1 ]; then
                arch=aarch64
            fi
            select_archive "$arch-apple-darwin" || { printf 'No macOS archive for %s in this release.\n' "$arch" >&2; exit 1; }
            ;;
        FreeBSD)
            select_archive "$arch-unknown-freebsd" || { printf 'No FreeBSD archive for %s in this release.\n' "$arch" >&2; exit 1; }
            ;;
        *) printf 'Unsupported operating system: %s\n' "$os" >&2; exit 1 ;;
    esac

    for command in curl tar mktemp; do
        command -v "$command" >/dev/null 2>&1 || { printf 'Required command missing: %s\n' "$command" >&2; exit 1; }
    done
    if command -v sha256sum >/dev/null 2>&1; then
        hash_command=sha256sum
    elif command -v shasum >/dev/null 2>&1; then
        hash_command=shasum
    elif command -v sha256 >/dev/null 2>&1; then
        hash_command=sha256
    else
        printf 'SHA-256 verification requires sha256sum, shasum, or sha256.\n' >&2
        exit 1
    fi

    install_dir=${RELEASE_PLZ_INSTALL_DIR:-"$HOME/.local/bin"}
    # Make paths absolute so paths starting with '-' cannot become command options.
    case "$install_dir" in /*) ;; *) install_dir="$PWD/$install_dir" ;; esac
    temp_dir=$(mktemp -d)
    install_temp=
    trap 'rm -rf "$temp_dir"; if [ -n "$install_temp" ]; then rm -rf "$install_temp"; fi' 0
    trap 'exit 1' HUP INT TERM
    archive="$temp_dir/archive.tar.gz"
    printf 'Downloading %s\n' "$url"
    curl --proto '=https' --proto-redir '=https' --tlsv1.2 -fsSL --output "$archive" "$url"
    case "$hash_command" in
        sha256sum) actual=$(sha256sum "$archive") ;;
        shasum) actual=$(shasum -a 256 "$archive") ;;
        sha256) actual=$(sha256 -q "$archive") ;;
    esac
    actual=${actual%% *}
    if [ "$actual" != "$checksum" ]; then
        printf 'SHA-256 checksum mismatch; nothing was installed.\n' >&2
        exit 1
    fi
    tar -xzf "$archive" -C "$temp_dir" -- "$@"
    for binary do
        if [ ! -f "$temp_dir/$binary" ] || [ -L "$temp_dir/$binary" ]; then
            printf 'Missing executable in archive: %s\n' "$binary" >&2
            exit 1
        fi
        if [ -d "$install_dir/$binary" ]; then
            printf 'Cannot replace a directory: %s\n' "$install_dir/$binary" >&2
            exit 1
        fi
    done
    mkdir -p "$install_dir"
    install_temp=$(mktemp -d "$install_dir/.release-plz.XXXXXXXX")
    for binary do
        cp "$temp_dir/$binary" "$install_temp/$binary"
        chmod 755 "$install_temp/$binary"
        # Rename replaces an old executable or symlink without following that symlink.
        mv -f "$install_temp/$binary" "$install_dir/$binary"
    done
    printf 'Installed to %s\nAdd this directory to PATH if it is not already there.\n' "$install_dir"
)

# Keep the call last so a truncated download cannot start installation.
release_plz_install
